// Rocky + Bubi voice lines for onboarding and the companion picker — public/audio/mascots/{line}-{vi|en}.mp3
// (generated by scripts/gen-audio-mascots.mjs). Muted together with the game sounds; one line plays at a time.
import { isGameSoundEnabled } from '@/lib/gameSound'

export type VoiceLang = 'vi' | 'en'
const LANG_KEY = 'vw_mascot_voice_lang'

let current: HTMLAudioElement | null = null
let queueToken = 0

export function getVoiceLang(): VoiceLang {
  if (typeof window === 'undefined') return 'vi'
  return window.localStorage.getItem(LANG_KEY) === 'en' ? 'en' : 'vi'
}

export function setVoiceLang(lang: VoiceLang) {
  window.localStorage.setItem(LANG_KEY, lang)
}

export function stopMascotVoice() {
  queueToken++
  current?.pause()
  current = null
}

// Plays the lines back to back after `delayMs` (lets a transition sfx finish first).
// Autoplay may be blocked before the first tap — that fails silently, like playSfx.
export function playMascotLines(lines: string[], { delayMs = 0, lang = getVoiceLang() }: { delayMs?: number; lang?: VoiceLang } = {}) {
  stopMascotVoice()
  if (typeof window === 'undefined' || !isGameSoundEnabled()) return
  const token = queueToken
  let i = 0
  const next = () => {
    if (token !== queueToken || i >= lines.length) return
    const audio = new Audio(`/audio/mascots/${lines[i++]}-${lang}.mp3`)
    current = audio
    audio.addEventListener('ended', next)
    audio.play().catch(() => {})
  }
  window.setTimeout(next, delayMs)
}
